 "content": "from collections import Counter


def _components(grid, background):
    h, w = len(grid), len(grid[0])
    seen, result = set(), []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == background or (r, c) in seen:
                continue
            seen.add((r, c))
            stack, cells = [(r, c)], []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] != background and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            result.append(cells)
    return result


def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    comps = _components(grid, background)
    source = max(comps, key=len)
    sr = [r for r, c in source]
    sc = [c for r, c in source]
    r0, r1, c0, c1 = min(sr), max(sr), min(sc), max(sc)
    pattern = [row[c0:c1 + 1] for row in grid[r0:r1 + 1]]
    ar, ac = (r1-r0)//2, (c1-c0)//2
    targets = [comp[0] for comp in comps if len(comp) == 1 and comp is not source]
    out = [row[:] for row in grid]
    for mr, mc in targets:
        for pr, row in enumerate(pattern):
            for pc, value in enumerate(row):
                rr, cc = mr + pr - ar, mc + pc - ac
                if 0 <= rr < h and 0 <= cc < w and value != background:
                    out[rr][cc] = value
    return out
